import numpy as np
def equation(t, A, params):
    p=params
    N = (p[0] + p[1]*A + p[2]*A**2 + p[3]*A**3 + p[4]*t + p[5]*t*A + p[6]*t*A**2
         + p[7]*t**2 + p[8]*t**2*A)
    return N/(1 + p[9]*t)

import numpy as np
t=df['t'].values; A=df['A'].values; y=df['dA_dt'].values
def basis(deg_a=3,deg_t=3):
    return np.column_stack([A**i*t**j for i in range(deg_a+1) for j in range(deg_t+1)])
def score(mult, deg_t=3):
    B=basis(3,deg_t)
    c,_,_,_=np.linalg.lstsq(B, y*mult,rcond=None)
    pred=B@c/mult
    return np.mean((y-pred)**2)/np.var(y)
